const now = new Date();

const opciones = { timeZone: 'Europe/Madrid', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false };

const fecha = now.toLocaleString('es-ES', opciones).replace(/^\w/, c => c.toUpperCase());

const hora = now.toLocaleString('es-ES', { timeZone: 'Europe/Madrid', hour: '2-digit', minute: '2-digit', hour12: false });

return [{ json: { fecha, hora } }];

let mensajes = [];

try {
  // Intenta leer desde "Obtiene todos los Mensajes"
  mensajes = $('Obtiene todos los Mensajes').first().json.message;
} catch (error) {
  try {
    // Si falla, intenta con "Obtiene todos los Mensajes1"
    mensajes = $('Obtiene todos los Mensajes1').first().json.message;
  } catch (error2) {
    mensajes = [];
  }
}

// Si no es array, lo convierte a vacío
if (!Array.isArray(mensajes)) {
  mensajes = [];
}

// Invierte el orden
const mensajesInvertidos = [...mensajes].reverse();

return [
  {
    json: {
      mensajes_invertidos: mensajesInvertidos
    }
  }
];

for (const item of $input.all()) {
  // Obtener el teléfono
  let wa_id = $input.first().json.body.contact_inbox.source_id;

  // Convertir a string y limpiar espacios/guiones
  wa_id = String(wa_id).replace(/[\s-]/g, '');

  // Lógica actualizada
  if (wa_id.startsWith('+')) {
    // Si tiene +, simplemente quitarlo (funciona para cualquier prefijo)
    wa_id = wa_id.substring(1);
  } else if (/^\d{9}$/.test(wa_id)) {
    // Si son exactamente 9 dígitos (número español sin prefijo), añadir 34
    wa_id = '34' + wa_id;
  }
  // Si ya tiene prefijo (34, 40, etc.) sin +, no hacer nada

  // Guardar el número procesado
  item.json.processed_wa_id = wa_id;
}

return $input.all();

const now = new Date();
now.setHours(now.getHours()); // Ajuste manual a UTC+2

const fecha = now.toLocaleDateString('es-ES', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  hour: '2-digit',
  minute: '2-digit'
}).replace(/^\w/, c => c.toUpperCase());

const hora = now.toLocaleTimeString('es-ES', {
  hour: '2-digit',
  minute: '2-digit'
});

return [{ json: { fecha, hora } }];

