// Construye el contexto del inmueble que vera el agente en su prompt.
// La referencia viene de los atributos del contacto en Chatwoot, que los deja
// el escenario de captacion al enviar la plantilla de bienvenida.
const fila = $input.first().json || {};
const f = $('Fecha').first().json || {};
const hay = !!fila.Referencia;

let descripcion;
if (hay) {
  const partes = [
    fila.Tipo,
    fila.Zona ? `en ${fila.Zona}` : null,
    fila.PrecioTexto ? `precio ${fila.PrecioTexto}` : null,
    fila.Superficie ? `superficie ${fila.Superficie}` : null,
    fila.Habitaciones ? String(fila.Habitaciones) : null,
  ].filter(Boolean);
  descripcion =
    `Referencia ${fila.Referencia} (${fila.Operacion || 'operacion no indicada'}). ` +
    partes.join(', ') + '.' +
    (fila.Titulo ? ` ${fila.Titulo}.` : '') +
    (fila.Url ? ` Ficha completa: ${fila.Url}` : '');
} else {
  // Sin referencia no se inventa nada: se le dice al agente que la pida.
  descripcion =
    'No se ha podido identificar el inmueble concreto por el que pregunta el cliente. ' +
    'Preguntale por la referencia, o por la zona y el tipo de vivienda que busca. ' +
    'No des datos de ningun inmueble que el cliente no te haya facilitado.';
}
return [{ json: { ...f, descripcion, referencia: fila.Referencia || '',
                  url_inmueble: fila.Url || '', tiene_inmueble: hay } }];
